CREATE OR REPLACE FUNCTION public.cms_initialize_unpublished()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO "CmsPage" ("organizationId", "draft") VALUES (
    NEW."id", jsonb_build_object('publicName', NEW."name", 'phone', NEW."phone", 'description', NULL, 'address', NULL, 'googleMapsUrl', NULL)
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notification_client_email_revision()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF lower(btrim(NEW."email")) IS DISTINCT FROM lower(btrim(OLD."email")) THEN
    NEW."emailRevision" := OLD."emailRevision" + 1;
  ELSE
    NEW."emailRevision" := OLD."emailRevision";
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_business_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE tenant TEXT; BEGIN
  tenant := COALESCE(NEW."organizationId", OLD."organizationId");
  IF EXISTS (SELECT 1 FROM "BusinessScheduleWindow" WHERE "organizationId"=tenant GROUP BY "dayOfWeek" HAVING count(*)>5) THEN
    RAISE EXCEPTION 'Too many business windows' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM "BusinessSchedule" WHERE "organizationId"=tenant AND "state"='CONFIRMED')
    AND (SELECT count(*) FROM "BusinessScheduleDay" WHERE "organizationId"=tenant)<>7 THEN
    RAISE EXCEPTION 'Incomplete confirmed business week' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $function$

